static
void kernel_2mm(int ni, int nj, int nk, int nl,
                DATA_TYPE alpha,
                DATA_TYPE beta,
                DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
                DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
                DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
                DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
                DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

  for (i = 0; i < _PB_NI; ++i) {
    DATA_TYPE *tmp_i = &tmp[i][0];
    DATA_TYPE *A_i = &A[i][0];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    {
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - j));
        vfloat32m1_t acc = __riscv_vfmv_v_f_f32m1(0.0f, vl);

        for (k = 0; k < _PB_NK; ++k) {
          float a = (float)(alpha * A_i[k]);
          vfloat32m1_t vb = __riscv_vle32_v_f32m1((const float *)&B[k][j], vl);
          acc = __riscv_vfmacc_vf_f32m1(acc, a, vb, vl);
        }

        __riscv_vse32_v_f32m1((float *)(tmp_i + j), acc, vl);
        j += (int)vl;
      }
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    {
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - j));
        vfloat64m1_t acc = __riscv_vfmv_v_f_f64m1(0.0, vl);

        for (k = 0; k < _PB_NK; ++k) {
          double a = (double)(alpha * A_i[k]);
          vfloat64m1_t vb = __riscv_vle64_v_f64m1((const double *)&B[k][j], vl);
          acc = __riscv_vfmacc_vf_f64m1(acc, a, vb, vl);
        }

        __riscv_vse64_v_f64m1((double *)(tmp_i + j), acc, vl);
        j += (int)vl;
      }
    }
#else
    for (j = 0; j < _PB_NJ; ++j) {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (k = 0; k < _PB_NK; ++k)
        sum += alpha * A_i[k] * B[k][j];
      tmp_i[j] = sum;
    }
#endif
  }

  for (i = 0; i < _PB_NI; ++i) {
    DATA_TYPE *D_i = &D[i][0];
    DATA_TYPE *tmp_i = &tmp[i][0];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    {
      for (j = 0; j < _PB_NL; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NL - j));
        vfloat32m1_t acc = __riscv_vle32_v_f32m1((const float *)(D_i + j), vl);
        acc = __riscv_vfmul_vf_f32m1(acc, (float)beta, vl);

        for (k = 0; k < _PB_NJ; ++k) {
          float t = (float)tmp_i[k];
          vfloat32m1_t vc = __riscv_vle32_v_f32m1((const float *)&C[k][j], vl);
          acc = __riscv_vfmacc_vf_f32m1(acc, t, vc, vl);
        }

        __riscv_vse32_v_f32m1((float *)(D_i + j), acc, vl);
        j += (int)vl;
      }
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    {
      for (j = 0; j < _PB_NL; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NL - j));
        vfloat64m1_t acc = __riscv_vle64_v_f64m1((const double *)(D_i + j), vl);
        acc = __riscv_vfmul_vf_f64m1(acc, (double)beta, vl);

        for (k = 0; k < _PB_NJ; ++k) {
          double t = (double)tmp_i[k];
          vfloat64m1_t vc = __riscv_vle64_v_f64m1((const double *)&C[k][j], vl);
          acc = __riscv_vfmacc_vf_f64m1(acc, t, vc, vl);
        }

        __riscv_vse64_v_f64m1((double *)(D_i + j), acc, vl);
        j += (int)vl;
      }
    }
#else
    for (j = 0; j < _PB_NL; ++j) {
      DATA_TYPE sum = D_i[j] * beta;
      for (k = 0; k < _PB_NJ; ++k)
        sum += tmp_i[k] * C[k][j];
      D_i[j] = sum;
    }
#endif
  }

#pragma endscop
}

static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		double E[ni][nj],
		double A[ni][nk],
		double B[nk][nj],
		double F[nj][nl],
		double C[nj][nm],
		double D[nm][nl],
		double G[ni][nl])
{
  int i, j, k;

#pragma scop

#if defined(__riscv_vector) && (defined(__GNUC__) || defined(__clang__))
  for (i = 0; i < _PB_NI; ++i) {
    for (j = 0; j < _PB_NJ; ++j)
      E[i][j] = 0.0;

    for (k = 0; k < _PB_NK; ++k) {
      double aik = A[i][k];
      int jj = 0;
      while (jj < _PB_NJ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - jj));
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[k][jj], vl);
        vfloat64m1_t ve = __riscv_vle64_v_f64m1(&E[i][jj], vl);
        ve = __riscv_vfmacc_vf_f64m1(ve, aik, vb, vl);
        __riscv_vse64_v_f64m1(&E[i][jj], ve, vl);
        jj += (int)vl;
      }
    }
  }

  for (i = 0; i < _PB_NJ; ++i) {
    for (j = 0; j < _PB_NL; ++j)
      F[i][j] = 0.0;

    for (k = 0; k < _PB_NM; ++k) {
      double cik = C[i][k];
      int jj = 0;
      while (jj < _PB_NL) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NL - jj));
        vfloat64m1_t vd = __riscv_vle64_v_f64m1(&D[k][jj], vl);
        vfloat64m1_t vf = __riscv_vle64_v_f64m1(&F[i][jj], vl);
        vf = __riscv_vfmacc_vf_f64m1(vf, cik, vd, vl);
        __riscv_vse64_v_f64m1(&F[i][jj], vf, vl);
        jj += (int)vl;
      }
    }
  }

  for (i = 0; i < _PB_NI; ++i) {
    for (j = 0; j < _PB_NL; ++j)
      G[i][j] = 0.0;

    for (k = 0; k < _PB_NJ; ++k) {
      double eik = E[i][k];
      int jj = 0;
      while (jj < _PB_NL) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NL - jj));
        vfloat64m1_t vf = __riscv_vle64_v_f64m1(&F[k][jj], vl);
        vfloat64m1_t vg = __riscv_vle64_v_f64m1(&G[i][jj], vl);
        vg = __riscv_vfmacc_vf_f64m1(vg, eik, vf, vl);
        __riscv_vse64_v_f64m1(&G[i][jj], vg, vl);
        jj += (int)vl;
      }
    }
  }
#else
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	E[i][j] = 0.0;
	for (k = 0; k < _PB_NK; ++k)
	  E[i][j] += A[i][k] * B[k][j];
      }

  for (i = 0; i < _PB_NJ; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	F[i][j] = 0.0;
	for (k = 0; k < _PB_NM; ++k)
	  F[i][j] += C[i][k] * D[k][j];
      }

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	G[i][j] = 0.0;
	for (k = 0; k < _PB_NJ; ++k)
	  G[i][j] += E[i][k] * F[k][j];
      }
#endif

#pragma endscop

}

#include <stddef.h>

#ifndef N
#define N 1024
#endif

#ifndef TSTEPS
#define TSTEPS 500
#endif

#ifndef DATA_TYPE
#define DATA_TYPE double
#endif

#ifndef SCALAR_VAL
#define SCALAR_VAL(x) ((DATA_TYPE)(x))
#endif

#ifndef POLYBENCH_2D
#define POLYBENCH_2D(var, dim1, dim2, n1, n2) var[dim1][dim2]
#endif

#ifndef _PB_N
#define _PB_N n
#endif

#ifndef _PB_TSTEPS
#define _PB_TSTEPS tsteps
#endif

static
void kernel_adi(int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  DX = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0)+mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0)+mul2;
  f = d;

  {
    const int n1 = _PB_N - 1;
    const DATA_TYPE one = SCALAR_VAL(1.0);
    const DATA_TYPE zero = SCALAR_VAL(0.0);
    const DATA_TYPE two = SCALAR_VAL(2.0);
    const DATA_TYPE one_plus_2d = one + two * d;
    const DATA_TYPE one_plus_2a = one + two * a;

    for (t = 1; t <= _PB_TSTEPS; t++) {

      for (i = 1; i < n1; i++) {
        v[0][i] = one;
        p[i][0] = zero;
        q[i][0] = v[0][i];

        {
          DATA_TYPE p_prev = p[i][0];
          DATA_TYPE q_prev = q[i][0];
          for (j = 1; j < n1; j++) {
            DATA_TYPE denom = a * p_prev + b;
            DATA_TYPE pj = -c / denom;
            DATA_TYPE qj =
              (-d * u[j][i-1] + one_plus_2d * u[j][i] - f * u[j][i+1] - a * q_prev) / denom;
            p[i][j] = pj;
            q[i][j] = qj;
            p_prev = pj;
            q_prev = qj;
          }
        }

        v[_PB_N-1][i] = one;
        for (j = _PB_N - 2; j >= 1; j--) {
          v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
        }
      }

      for (i = 1; i < n1; i++) {
        u[i][0] = one;
        p[i][0] = zero;
        q[i][0] = u[i][0];

        {
          DATA_TYPE p_prev = p[i][0];
          DATA_TYPE q_prev = q[i][0];
          for (j = 1; j < n1; j++) {
            DATA_TYPE denom = d * p_prev + e;
            DATA_TYPE pj = -f / denom;
            DATA_TYPE qj =
              (-a * v[i-1][j] + one_plus_2a * v[i][j] - c * v[i+1][j] - d * q_prev) / denom;
            p[i][j] = pj;
            q[i][j] = qj;
            p_prev = pj;
            q_prev = qj;
          }
        }

        u[i][_PB_N-1] = one;
        for (j = _PB_N - 2; j >= 1; j--) {
          u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
        }
      }
    }
  }

#pragma endscop
}

static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
  {
    for (j = 0; j < _PB_N; )
      {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
        vfloat64m1_t vy = __riscv_vfmv_v_f_f64m1((double)0.0, vl);
        __riscv_vse64_v_f64m1(&y[j], vy, vl);
        j += (int)vl;
      }

    for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE sum = SCALAR_VAL(0.0);
        DATA_TYPE *Ai = &A[i][0];

        for (j = 0; j < _PB_N; )
	  {
	    size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
	    vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[j], vl);
	    vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
	    vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(va, vx, vl);
	    vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(
	        vprod,
	        __riscv_vfmv_v_f_f64m1((double)0.0, vl),
	        vl);
	    sum += (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vred);
	    j += (int)vl;
	  }

        tmp[i] = sum;

        for (j = 0; j < _PB_N; )
	  {
	    size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
	    vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[j], vl);
	    vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[j], vl);
	    vy = __riscv_vfmacc_vf_f64m1(vy, (double)sum, va, vl);
	    __riscv_vse64_v_f64m1(&y[j], vy, vl);
	    j += (int)vl;
	  }
      }
  }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  {
    for (j = 0; j < _PB_N; )
      {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
        vfloat32m1_t vy = __riscv_vfmv_v_f_f32m1((float)0.0f, vl);
        __riscv_vse32_v_f32m1(&y[j], vy, vl);
        j += (int)vl;
      }

    for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE sum = SCALAR_VAL(0.0);
        DATA_TYPE *Ai = &A[i][0];

        for (j = 0; j < _PB_N; )
	  {
	    size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
	    vfloat32m1_t va = __riscv_vle32_v_f32m1(&Ai[j], vl);
	    vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[j], vl);
	    vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(va, vx, vl);
	    vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(
	        vprod,
	        __riscv_vfmv_v_f_f32m1((float)0.0f, vl),
	        vl);
	    sum += (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vred);
	    j += (int)vl;
	  }

        tmp[i] = sum;

        for (j = 0; j < _PB_N; )
	  {
	    size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
	    vfloat32m1_t va = __riscv_vle32_v_f32m1(&Ai[j], vl);
	    vfloat32m1_t vy = __riscv_vle32_v_f32m1(&y[j], vl);
	    vy = __riscv_vfmacc_vf_f32m1(vy, (float)sum, va, vl);
	    __riscv_vse32_v_f32m1(&y[j], vy, vl);
	    j += (int)vl;
	  }
      }
  }
#else
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

  for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
	sum = sum + A[i][j] * x[j];
      tmp[i] = sum;
      for (j = 0; j < _PB_N; j++)
	y[j] = y[j] + A[i][j] * sum;
    }
#endif
#pragma endscop

}

static
void kernel_bicg(int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(s,M,m),
                 DATA_TYPE POLYBENCH_1D(q,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE qi = SCALAR_VAL(0.0);
    DATA_TYPE ri = r[i];
    DATA_TYPE *a_row = A[i];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    j = 0;
    {
      vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
      vfloat32m1_t vq_acc = vzero;

      while (j < _PB_M)
      {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_M - j));
        vfloat32m1_t va = __riscv_vle32_v_f32m1(&a_row[j], vl);
        vfloat32m1_t vp = __riscv_vle32_v_f32m1(&p[j], vl);
        vfloat32m1_t vs = __riscv_vle32_v_f32m1(&s[j], vl);

        vs = __riscv_vfmacc_vf_f32m1(vs, ri, va, vl);
        __riscv_vse32_v_f32m1(&s[j], vs, vl);

        vq_acc = __riscv_vfmacc_vv_f32m1(vq_acc, va, vp, vl);
        j += (int)vl;
      }

      qi = __riscv_vfmv_f_s_f32m1_f32(
             __riscv_vfredusum_vs_f32m1_f32m1(vq_acc, vzero, 1));
    }
    q[i] = qi;

#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    j = 0;
    {
      vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
      vfloat64m1_t vq_acc = vzero;

      while (j < _PB_M)
      {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - j));
        vfloat64m1_t va = __riscv_vle64_v_f64m1(&a_row[j], vl);
        vfloat64m1_t vp = __riscv_vle64_v_f64m1(&p[j], vl);
        vfloat64m1_t vs = __riscv_vle64_v_f64m1(&s[j], vl);

        vs = __riscv_vfmacc_vf_f64m1(vs, ri, va, vl);
        __riscv_vse64_v_f64m1(&s[j], vs, vl);

        vq_acc = __riscv_vfmacc_vv_f64m1(vq_acc, va, vp, vl);
        j += (int)vl;
      }

      qi = __riscv_vfmv_f_s_f64m1_f64(
             __riscv_vfredusum_vs_f64m1_f64m1(vq_acc, vzero, 1));
    }
    q[i] = qi;

#else
    for (j = 0; j < _PB_M; j++)
    {
      s[j] = s[j] + ri * a_row[j];
      qi = qi + a_row[j] * p[j];
    }
    q[i] = qi;
#endif
  }
#pragma endscop
}

static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

    for (j = 0; j < i; j++) {
      DATA_TYPE aij = A[i][j];

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic) && defined(DATA_TYPE_IS_DOUBLE)
      {
        int kk = 0;
        int len = j;
        DATA_TYPE acc = 0.0;

        while (len > 0) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)len);
          vfloat64m1_t vi = __riscv_vle64_v_f64m1(&A[i][kk], vl);
          vfloat64m1_t vj = __riscv_vle64_v_f64m1(&A[j][kk], vl);
          vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vi, vj, vl);
          vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
          vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vzero, vm, vzero, vl);
          acc += __riscv_vfmv_f_s_f64m1_f64(vred);

          kk += (int)vl;
          len -= (int)vl;
        }

        aij -= acc;
      }
#elif defined(__riscv_vector) && defined(__riscv_v_intrinsic) && defined(DATA_TYPE_IS_FLOAT)
      {
        int kk = 0;
        int len = j;
        DATA_TYPE acc = 0.0f;

        while (len > 0) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)len);
          vfloat32m1_t vi = __riscv_vle32_v_f32m1(&A[i][kk], vl);
          vfloat32m1_t vj = __riscv_vle32_v_f32m1(&A[j][kk], vl);
          vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(vi, vj, vl);
          vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
          vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vzero, vm, vzero, vl);
          acc += __riscv_vfmv_f_s_f32m1_f32(vred);

          kk += (int)vl;
          len -= (int)vl;
        }

        aij -= acc;
      }
#else
      for (k = 0; k < j; k++) {
        aij -= A[i][k] * A[j][k];
      }
#endif

      A[i][j] = aij / A[j][j];
    }

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic) && defined(DATA_TYPE_IS_DOUBLE)
    {
      int kk = 0;
      int len = i;
      DATA_TYPE acc = 0.0;

      while (len > 0) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)len);
        vfloat64m1_t vi = __riscv_vle64_v_f64m1(&A[i][kk], vl);
        vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vi, vi, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vzero, vm, vzero, vl);
        acc += __riscv_vfmv_f_s_f64m1_f64(vred);

        kk += (int)vl;
        len -= (int)vl;
      }

      A[i][i] -= acc;
    }
#elif defined(__riscv_vector) && defined(__riscv_v_intrinsic) && defined(DATA_TYPE_IS_FLOAT)
    {
      int kk = 0;
      int len = i;
      DATA_TYPE acc = 0.0f;

      while (len > 0) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)len);
        vfloat32m1_t vi = __riscv_vle32_v_f32m1(&A[i][kk], vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(vi, vi, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
        vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vzero, vm, vzero, vl);
        acc += __riscv_vfmv_f_s_f32m1_f32(vred);

        kk += (int)vl;
        len -= (int)vl;
      }

      A[i][i] -= acc;
    }
#else
    for (k = 0; k < i; k++) {
      A[i][i] -= A[i][k] * A[i][k];
    }
#endif

    A[i][i] = SQRT_FUN(A[i][i]);
  }
#pragma endscop

}

static
void kernel_correlation(int m, int n,
			double float_n,
			double data[n][m],
			double corr[m][m],
			double mean[m],
			double stddev[m])
{
  int i, j, k;
  double eps = 0.1;

#pragma scop
  {
    double sqrt_float_n = SQRT_FUN(float_n);

    for (j = 0; j < m; j++)
    {
      double sum = 0.0;
      for (i = 0; i < n; i++)
        sum += data[i][j];
      mean[j] = sum / float_n;
    }

    for (j = 0; j < m; j++)
    {
      double sum = 0.0;
      double mj = mean[j];
      for (i = 0; i < n; i++)
      {
        double d = data[i][j] - mj;
        sum += d * d;
      }
      stddev[j] = sum / float_n;
      stddev[j] = SQRT_FUN(stddev[j]);
      stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    }

    for (i = 0; i < n; i++)
    {
#if defined(__riscv_vector)
      j = 0;
      for (; j < m; )
      {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(m - j));
        vfloat64m1_t vdata = __riscv_vle64_v_f64m1(&data[i][j], vl);
        vfloat64m1_t vmean = __riscv_vle64_v_f64m1(&mean[j], vl);
        vfloat64m1_t vstd  = __riscv_vle64_v_f64m1(&stddev[j], vl);
        vfloat64m1_t vden  = __riscv_vfmul_vf_f64m1(vstd, sqrt_float_n, vl);
        vdata = __riscv_vfsub_vv_f64m1(vdata, vmean, vl);
        vdata = __riscv_vfdiv_vv_f64m1(vdata, vden, vl);
        __riscv_vse64_v_f64m1(&data[i][j], vdata, vl);
        j += (int)vl;
      }
#else
      for (j = 0; j < m; j++)
      {
        data[i][j] -= mean[j];
        data[i][j] /= sqrt_float_n * stddev[j];
      }
#endif
    }

    for (i = 0; i < m - 1; i++)
    {
      corr[i][i] = 1.0;
      for (j = i + 1; j < m; j++)
      {
        double sum = 0.0;
        for (k = 0; k < n; k++)
          sum += data[k][i] * data[k][j];
        corr[i][j] = sum;
        corr[j][i] = sum;
      }
    }
    corr[m - 1][m - 1] = 1.0;
  }
#pragma endscop
}

