            else
              {
                for (; k < _PB_N; )
                  {
                    size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - k));
                    vfloat32m1_t vi = __riscv_vlse32_v_f32m1(&data[k][i], stride, vl);
                    vfloat32m1_t vj = __riscv_vlse32_v_f32m1(&data[k][j], stride, vl);
                    vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(SCALAR_VAL(0.0), vl);
                    vfloat32m1_t vacc = __riscv_vfmacc_vv_f32m1(vzero, vi, vj, vl);
                    vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(
                        vacc, __riscv_vfmv_v_f_f32m1(SCALAR_VAL(0.0), 1), vl);
                    sum += __riscv_vfmv_f_s_f32m1_f32(vred);
                    k += (int)vl;
                  }
              }

            sum /= denom;
            cov_i[j] = sum;
            cov[j][i] = sum;
          }
      }
  }
#else
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        cov[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; k++)
