static
void kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h))
{
  int i, j;
  DATA_TYPE xm1, tm1, ym1, ym2;
  DATA_TYPE xp1, xp2;
  DATA_TYPE tp1, tp2;
  DATA_TYPE yp1, yp2;

  DATA_TYPE k;
  DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
  DATA_TYPE b1, b2, c1, c2;

#pragma scop
  {
    const DATA_TYPE exp_ma = EXP_FUN(-alpha);
    const DATA_TYPE exp_m2a = EXP_FUN(SCALAR_VAL(-2.0) * alpha);

    k =
        (SCALAR_VAL(1.0) - exp_ma) * (SCALAR_VAL(1.0) - exp_ma) /
        (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * exp_ma -
         EXP_FUN(SCALAR_VAL(2.0) * alpha));

    a1 = a5 = k;
    a2 = a6 = k * exp_ma * (alpha - SCALAR_VAL(1.0));
    a3 = a7 = k * exp_ma * (alpha + SCALAR_VAL(1.0));
    a4 = a8 = -k * exp_m2a;
    b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
    b2 = -exp_m2a;
    c1 = c2 = 1;
  }

  for (i = 0; i < _PB_W; i++) {
    ym1 = SCALAR_VAL(0.0);
    ym2 = SCALAR_VAL(0.0);
    xm1 = SCALAR_VAL(0.0);
    for (j = 0; j < _PB_H; j++) {
      DATA_TYPE x = imgIn[i][j];
      DATA_TYPE yv = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;
      y1[i][j] = yv;
      xm1 = x;
      ym2 = ym1;
      ym1 = yv;
    }
  }

  for (i = 0; i < _PB_W; i++) {
    yp1 = SCALAR_VAL(0.0);
    yp2 = SCALAR_VAL(0.0);
    xp1 = SCALAR_VAL(0.0);
    xp2 = SCALAR_VAL(0.0);
    for (j = _PB_H - 1; j >= 0; j--) {
      DATA_TYPE yv = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
      y2[i][j] = yv;
      xp2 = xp1;
      xp1 = imgIn[i][j];
      yp2 = yp1;
      yp1 = yv;
    }
  }

  for (i = 0; i < _PB_W; i++) {
#if defined(__riscv_vector) && defined(__has_include)
#if __has_include(<riscv_vector.h>)
#define KERNEL_DERICHE_HAVE_RVV 1
#endif
#endif

#if defined(KERNEL_DERICHE_HAVE_RVV)
#if defined(DATA_TYPE_IS_FLOAT)
    {
      int jj = 0;
      while (jj < _PB_H) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_H - jj));
        vfloat32m1_t vy1v = __riscv_vle32_v_f32m1((const float *)&y1[i][jj], vl);
        vfloat32m1_t vy2v = __riscv_vle32_v_f32m1((const float *)&y2[i][jj], vl);
        vfloat32m1_t vout = __riscv_vfadd_vv_f32m1(vy1v, vy2v, vl);
        vout = __riscv_vfmul_vf_f32m1(vout, (float)c1, vl);
        __riscv_vse32_v_f32m1((float *)&imgOut[i][jj], vout, vl);
        jj += (int)vl;
      }
    }
#elif defined(DATA_TYPE_IS_DOUBLE)
    {
      int jj = 0;
      while (jj < _PB_H) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_H - jj));
        vfloat64m1_t vy1v = __riscv_vle64_v_f64m1((const double *)&y1[i][jj], vl);
        vfloat64m1_t vy2v = __riscv_vle64_v_f64m1((const double *)&y2[i][jj], vl);
        vfloat64m1_t vout = __riscv_vfadd_vv_f64m1(vy1v, vy2v, vl);
        vout = __riscv_vfmul_vf_f64m1(vout, (double)c1, vl);
        __riscv_vse64_v_f64m1((double *)&imgOut[i][jj], vout, vl);
        jj += (int)vl;
      }
    }
#else
    for (j = 0; j < _PB_H; j++) {
      imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    }
#endif
#else
    for (j = 0; j < _PB_H; j++) {
      imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    }
#endif
  }

  for (j = 0; j < _PB_H; j++) {
    tm1 = SCALAR_VAL(0.0);
    ym1 = SCALAR_VAL(0.0);
    ym2 = SCALAR_VAL(0.0);
    for (i = 0; i < _PB_W; i++) {
      DATA_TYPE x = imgOut[i][j];
      DATA_TYPE yv = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;
      y1[i][j] = yv;
      tm1 = x;
      ym2 = ym1;
      ym1 = yv;
    }
  }

  for (j = 0; j < _PB_H; j++) {
    tp1 = SCALAR_VAL(0.0);
    tp2 = SCALAR_VAL(0.0);
    yp1 = SCALAR_VAL(0.0);
    yp2 = SCALAR_VAL(0.0);
    for (i = _PB_W - 1; i >= 0; i--) {
      DATA_TYPE yv = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
      y2[i][j] = yv;
      tp2 = tp1;
      tp1 = imgOut[i][j];
      yp2 = yp1;
      yp1 = yv;
    }
  }

  for (i = 0; i < _PB_W; i++) {
#if defined(KERNEL_DERICHE_HAVE_RVV)
#if defined(DATA_TYPE_IS_FLOAT)
    {
      int jj = 0;
      while (jj < _PB_H) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_H - jj));
        vfloat32m1_t vy1v = __riscv_vle32_v_f32m1((const float *)&y1[i][jj], vl);
        vfloat32m1_t vy2v = __riscv_vle32_v_f32m1((const float *)&y2[i][jj], vl);
        vfloat32m1_t vout = __riscv_vfadd_vv_f32m1(vy1v, vy2v, vl);
        vout = __riscv_vfmul_vf_f32m1(vout, (float)c2, vl);
        __riscv_vse32_v_f32m1((float *)&imgOut[i][jj], vout, vl);
        jj += (int)vl;
      }
    }
#elif defined(DATA_TYPE_IS_DOUBLE)
    {
      int jj = 0;
      while (jj < _PB_H) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_H - jj));
        vfloat64m1_t vy1v = __riscv_vle64_v_f64m1((const double *)&y1[i][jj], vl);
        vfloat64m1_t vy2v = __riscv_vle64_v_f64m1((const double *)&y2[i][jj], vl);
        vfloat64m1_t vout = __riscv_vfadd_vv_f64m1(vy1v, vy2v, vl);
        vout = __riscv_vfmul_vf_f64m1(vout, (double)c2, vl);
        __riscv_vse64_v_f64m1((double *)&imgOut[i][jj], vout, vl);
        jj += (int)vl;
      }
    }
#else
    for (j = 0; j < _PB_H; j++) {
      imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    }
#endif
#else
    for (j = 0; j < _PB_H; j++) {
      imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    }
#endif
  }

#pragma endscop
}

void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {
      DATA_TYPE *A_rq = &A[r][q][0];

#if defined(__riscv_vector)
#if defined(DATA_TYPE_IS_FLOAT)
      {
        int avl_init = _PB_NP;
        int p_init = 0;
        while (avl_init > 0) {
          size_t vl = __riscv_vsetvl_e32m1(avl_init);
          vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1((float)SCALAR_VAL(0.0), vl);
          __riscv_vse32_v_f32m1((float *)&sum[p_init], vzero, vl);
          p_init += (int)vl;
          avl_init -= (int)vl;
        }

        for (s = 0; s < _PB_NP; s++) {
          float a_scalar = (float)A_rq[s];
          const float *c4_row = (const float *)&C4[s][0];
          int avl = _PB_NP;
          int p_vec = 0;
          while (avl > 0) {
            size_t vl = __riscv_vsetvl_e32m1(avl);
            vfloat32m1_t vsum = __riscv_vle32_v_f32m1((const float *)&sum[p_vec], vl);
            vfloat32m1_t vc4 = __riscv_vle32_v_f32m1(&c4_row[p_vec], vl);
            vsum = __riscv_vfmacc_vf_f32m1(vsum, a_scalar, vc4, vl);
            __riscv_vse32_v_f32m1((float *)&sum[p_vec], vsum, vl);
            p_vec += (int)vl;
            avl -= (int)vl;
          }
        }

        {
          int avl_copy = _PB_NP;
          int p_copy = 0;
          while (avl_copy > 0) {
            size_t vl = __riscv_vsetvl_e32m1(avl_copy);
            vfloat32m1_t vsum = __riscv_vle32_v_f32m1((const float *)&sum[p_copy], vl);
            __riscv_vse32_v_f32m1((float *)&A_rq[p_copy], vsum, vl);
            p_copy += (int)vl;
            avl_copy -= (int)vl;
          }
        }
      }
#elif defined(DATA_TYPE_IS_DOUBLE)
      {
        int avl_init = _PB_NP;
        int p_init = 0;
        while (avl_init > 0) {
          size_t vl = __riscv_vsetvl_e64m1(avl_init);
          vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1((double)SCALAR_VAL(0.0), vl);
          __riscv_vse64_v_f64m1((double *)&sum[p_init], vzero, vl);
          p_init += (int)vl;
          avl_init -= (int)vl;
        }

        for (s = 0; s < _PB_NP; s++) {
          double a_scalar = (double)A_rq[s];
          const double *c4_row = (const double *)&C4[s][0];
          int avl = _PB_NP;
          int p_vec = 0;
          while (avl > 0) {
            size_t vl = __riscv_vsetvl_e64m1(avl);
            vfloat64m1_t vsum = __riscv_vle64_v_f64m1((const double *)&sum[p_vec], vl);
            vfloat64m1_t vc4 = __riscv_vle64_v_f64m1(&c4_row[p_vec], vl);
            vsum = __riscv_vfmacc_vf_f64m1(vsum, a_scalar, vc4, vl);
            __riscv_vse64_v_f64m1((double *)&sum[p_vec], vsum, vl);
            p_vec += (int)vl;
            avl -= (int)vl;
          }
        }

        {
          int avl_copy = _PB_NP;
          int p_copy = 0;
          while (avl_copy > 0) {
            size_t vl = __riscv_vsetvl_e64m1(avl_copy);
            vfloat64m1_t vsum = __riscv_vle64_v_f64m1((const double *)&sum[p_copy], vl);
            __riscv_vse64_v_f64m1((double *)&A_rq[p_copy], vsum, vl);
            p_copy += (int)vl;
            avl_copy -= (int)vl;
          }
        }
      }
#else
      for (p = 0; p < _PB_NP; p++) {
        sum[p] = SCALAR_VAL(0.0);
      }
      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_scalar = A_rq[s];
        for (p = 0; p < _PB_NP; p++) {
          sum[p] += a_scalar * C4[s][p];
        }
      }
      for (p = 0; p < _PB_NP; p++) {
        A_rq[p] = sum[p];
      }
#endif
#else
      for (p = 0; p < _PB_NP; p++) {
        sum[p] = SCALAR_VAL(0.0);
      }
      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_scalar = A_rq[s];
        for (p = 0; p < _PB_NP; p++) {
          sum[p] += a_scalar * C4[s][p];
        }
      }
      for (p = 0; p < _PB_NP; p++) {
        A_rq[p] = sum[p];
      }
#endif
    }
  }
#pragma endscop
}

static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE z[N];
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  y[0] = -r[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r[0];

  for (k = 1; k < _PB_N; k++) {
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;
    sum = SCALAR_VAL(0.0);

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic) && defined(DATA_TYPE_IS_DOUBLE)
    {
      int rem = k;
      int idx = 0;
      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1(rem);
        vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[idx], vl);

        DATA_TYPE rt[256];
        size_t t;
        for (t = 0; t < vl; ++t) {
          rt[t] = r[k - idx - 1 - (int)t];
        }

        vfloat64m1_t vr = __riscv_vle64_v_f64m1(rt, vl);
        vfloat64m1_t prod = __riscv_vfmul_vv_f64m1(vr, vy, vl);

        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.0), vl);
        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vzero, prod, vzero, vl);
        sum += __riscv_vfmv_f_s_f64m1_f64(vred);

        idx += (int)vl;
        rem -= (int)vl;
      }
    }
#else
    for (i = 0; i < k; i++) {
      sum += r[k - i - 1] * y[i];
    }
#endif

    alpha = -(r[k] + sum) / beta;

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic) && defined(DATA_TYPE_IS_DOUBLE)
    {
      int rem = k;
      int idx = 0;
      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1(rem);
        vfloat64m1_t vyf = __riscv_vle64_v_f64m1(&y[idx], vl);

        DATA_TYPE yt[256];
        size_t t;
        for (t = 0; t < vl; ++t) {
          yt[t] = y[k - idx - 1 - (int)t];
        }

        vfloat64m1_t vyr = __riscv_vle64_v_f64m1(yt, vl);
        vfloat64m1_t vz = __riscv_vfmacc_vf_f64m1(vyf, alpha, vyr, vl);
        __riscv_vse64_v_f64m1(&z[idx], vz, vl);

        idx += (int)vl;
        rem -= (int)vl;
      }
    }

    {
      int rem = k;
      int idx = 0;
      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1(rem);
        vfloat64m1_t vz = __riscv_vle64_v_f64m1(&z[idx], vl);
        __riscv_vse64_v_f64m1(&y[idx], vz, vl);
        idx += (int)vl;
        rem -= (int)vl;
      }
    }
#else
    for (i = 0; i < k; i++) {
      z[i] = y[i] + alpha * y[k - i - 1];
    }
    for (i = 0; i < k; i++) {
      y[i] = z[i];
    }
#endif

    y[k] = alpha;
  }
#pragma endscop
}

static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

#if defined(__riscv_vector) && defined(__has_include)
#if __has_include(<riscv_vector.h>)
#define KERNEL_FDTD_2D_USE_RVV 1
#include <riscv_vector.h>
#endif
#endif

#if defined(KERNEL_FDTD_2D_USE_RVV) && defined(DATA_TYPE_IS_FLOAT)

  for (t = 0; t < _PB_TMAX; t++)
    {
      {
        DATA_TYPE fv = _fict_[t];
        size_t jv = 0;
        while (jv < (size_t)_PB_NY) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NY - (int)jv));
          vfloat32m1_t vv = __riscv_vfmv_v_f_f32m1(fv, vl);
          __riscv_vse32_v_f32m1(&ey[0][jv], vv, vl);
          jv += vl;
        }
      }

      for (i = 1; i < _PB_NX; i++) {
        DATA_TYPE *eyi  = &ey[i][0];
        DATA_TYPE *hzi  = &hz[i][0];
        DATA_TYPE *hzim = &hz[i-1][0];
        size_t jv = 0;
        while (jv < (size_t)_PB_NY) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NY - (int)jv));
          vfloat32m1_t vey  = __riscv_vle32_v_f32m1(eyi  + jv, vl);
          vfloat32m1_t vhz  = __riscv_vle32_v_f32m1(hzi  + jv, vl);
          vfloat32m1_t vhzm = __riscv_vle32_v_f32m1(hzim + jv, vl);
          vfloat32m1_t vdiff = __riscv_vfsub_vv_f32m1(vhz, vhzm, vl);
          vfloat32m1_t vscaled = __riscv_vfmul_vf_f32m1(vdiff, (float)0.5f, vl);
          vey = __riscv_vfsub_vv_f32m1(vey, vscaled, vl);
          __riscv_vse32_v_f32m1(eyi + jv, vey, vl);
          jv += vl;
        }
      }

      for (i = 0; i < _PB_NX; i++) {
        DATA_TYPE *exi = &ex[i][0];
        DATA_TYPE *hzi = &hz[i][0];
        size_t jv = 1;
        while (jv < (size_t)_PB_NY) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NY - (int)jv));
          vfloat32m1_t vex   = __riscv_vle32_v_f32m1(exi + jv, vl);
          vfloat32m1_t vhz   = __riscv_vle32_v_f32m1(hzi + jv, vl);
          vfloat32m1_t vhz_l = __riscv_vle32_v_f32m1(hzi + jv - 1, vl);
          vfloat32m1_t vdiff = __riscv_vfsub_vv_f32m1(vhz, vhz_l, vl);
          vfloat32m1_t vscaled = __riscv_vfmul_vf_f32m1(vdiff, (float)0.5f, vl);
          vex = __riscv_vfsub_vv_f32m1(vex, vscaled, vl);
          __riscv_vse32_v_f32m1(exi + jv, vex, vl);
          jv += vl;
        }
      }

      for (i = 0; i < _PB_NX - 1; i++) {
        DATA_TYPE *hzi   = &hz[i][0];
        DATA_TYPE *exi   = &ex[i][0];
        DATA_TYPE *eyi   = &ey[i][0];
        DATA_TYPE *eyip1 = &ey[i+1][0];
        size_t jv = 0;
        while (jv < (size_t)(_PB_NY - 1)) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)((_PB_NY - 1) - (int)jv));
          vfloat32m1_t vhz   = __riscv_vle32_v_f32m1(hzi   + jv, vl);
          vfloat32m1_t vex0  = __riscv_vle32_v_f32m1(exi   + jv, vl);
          vfloat32m1_t vex1  = __riscv_vle32_v_f32m1(exi   + jv + 1, vl);
          vfloat32m1_t vey0  = __riscv_vle32_v_f32m1(eyi   + jv, vl);
          vfloat32m1_t vey1  = __riscv_vle32_v_f32m1(eyip1 + jv, vl);
          vfloat32m1_t vtmp1 = __riscv_vfsub_vv_f32m1(vex1, vex0, vl);
          vfloat32m1_t vtmp2 = __riscv_vfsub_vv_f32m1(vey1, vey0, vl);
          vfloat32m1_t vsum  = __riscv_vfadd_vv_f32m1(vtmp1, vtmp2, vl);
          vfloat32m1_t vscaled = __riscv_vfmul_vf_f32m1(vsum, (float)0.7f, vl);
          vhz = __riscv_vfsub_vv_f32m1(vhz, vscaled, vl);
          __riscv_vse32_v_f32m1(hzi + jv, vhz, vl);
          jv += vl;
        }
      }
    }

#elif defined(KERNEL_FDTD_2D_USE_RVV) && defined(DATA_TYPE_IS_DOUBLE)

  for (t = 0; t < _PB_TMAX; t++)
    {
      {
        DATA_TYPE fv = _fict_[t];
        size_t jv = 0;
        while (jv < (size_t)_PB_NY) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NY - (int)jv));
          vfloat64m1_t vv = __riscv_vfmv_v_f_f64m1(fv, vl);
          __riscv_vse64_v_f64m1(&ey[0][jv], vv, vl);
          jv += vl;
        }
      }

      for (i = 1; i < _PB_NX; i++) {
        DATA_TYPE *eyi  = &ey[i][0];
        DATA_TYPE *hzi  = &hz[i][0];
        DATA_TYPE *hzim = &hz[i-1][0];
        size_t jv = 0;
        while (jv < (size_t)_PB_NY) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NY - (int)jv));
          vfloat64m1_t vey  = __riscv_vle64_v_f64m1(eyi  + jv, vl);
          vfloat64m1_t vhz  = __riscv_vle64_v_f64m1(hzi  + jv, vl);
          vfloat64m1_t vhzm = __riscv_vle64_v_f64m1(hzim + jv, vl);
          vfloat64m1_t vdiff = __riscv_vfsub_vv_f64m1(vhz, vhzm, vl);
          vfloat64m1_t vscaled = __riscv_vfmul_vf_f64m1(vdiff, (double)0.5, vl);
          vey = __riscv_vfsub_vv_f64m1(vey, vscaled, vl);
          __riscv_vse64_v_f64m1(eyi + jv, vey, vl);
          jv += vl;
        }
      }

      for (i = 0; i < _PB_NX; i++) {
        DATA_TYPE *exi = &ex[i][0];
        DATA_TYPE *hzi = &hz[i][0];
        size_t jv = 1;
        while (jv < (size_t)_PB_NY) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NY - (int)jv));
          vfloat64m1_t vex   = __riscv_vle64_v_f64m1(exi + jv, vl);
          vfloat64m1_t vhz   = __riscv_vle64_v_f64m1(hzi + jv, vl);
          vfloat64m1_t vhz_l = __riscv_vle64_v_f64m1(hzi + jv - 1, vl);
          vfloat64m1_t vdiff = __riscv_vfsub_vv_f64m1(vhz, vhz_l, vl);
          vfloat64m1_t vscaled = __riscv_vfmul_vf_f64m1(vdiff, (double)0.5, vl);
          vex = __riscv_vfsub_vv_f64m1(vex, vscaled, vl);
          __riscv_vse64_v_f64m1(exi + jv, vex, vl);
          jv += vl;
        }
      }

      for (i = 0; i < _PB_NX - 1; i++) {
        DATA_TYPE *hzi   = &hz[i][0];
        DATA_TYPE *exi   = &ex[i][0];
        DATA_TYPE *eyi   = &ey[i][0];
        DATA_TYPE *eyip1 = &ey[i+1][0];
        size_t jv = 0;
        while (jv < (size_t)(_PB_NY - 1)) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)((_PB_NY - 1) - (int)jv));
          vfloat64m1_t vhz   = __riscv_vle64_v_f64m1(hzi   + jv, vl);
          vfloat64m1_t vex0  = __riscv_vle64_v_f64m1(exi   + jv, vl);
          vfloat64m1_t vex1  = __riscv_vle64_v_f64m1(exi   + jv + 1, vl);
          vfloat64m1_t vey0  = __riscv_vle64_v_f64m1(eyi   + jv, vl);
          vfloat64m1_t vey1  = __riscv_vle64_v_f64m1(eyip1 + jv, vl);
          vfloat64m1_t vtmp1 = __riscv_vfsub_vv_f64m1(vex1, vex0, vl);
          vfloat64m1_t vtmp2 = __riscv_vfsub_vv_f64m1(vey1, vey0, vl);
          vfloat64m1_t vsum  = __riscv_vfadd_vv_f64m1(vtmp1, vtmp2, vl);
          vfloat64m1_t vscaled = __riscv_vfmul_vf_f64m1(vsum, (double)0.7, vl);
          vhz = __riscv_vfsub_vv_f64m1(vhz, vscaled, vl);
          __riscv_vse64_v_f64m1(hzi + jv, vhz, vl);
          jv += vl;
        }
      }
    }

#else

  for(t = 0; t < _PB_TMAX; t++)
    {
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];
      for (i = 1; i < _PB_NX; i++)
	for (j = 0; j < _PB_NY; j++)
	  ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
      for (i = 0; i < _PB_NX; i++)
	for (j = 1; j < _PB_NY; j++)
	  ex[i][j] = ex[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i][j-1]);
      for (i = 0; i < _PB_NX - 1; i++)
	for (j = 0; j < _PB_NY - 1; j++)
	  hz[i][j] = hz[i][j] - SCALAR_VAL(0.7)*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
    }

#endif

#pragma endscop
}

static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++) {
    DATA_TYPE *path_k = path[k];

    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE *path_i = path[i];
      DATA_TYPE pik = path_i[k];

      for (j = 0; j < _PB_N; j++) {
        DATA_TYPE alt = pik + path_k[j];
        path_i[j] = (path_i[j] < alt) ? path_i[j] : alt;
      }
    }
  }
#pragma endscop

}

static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *c_row = &C[i][0];
    DATA_TYPE *a_row = &A[i][0];

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_DOUBLE)
    for (j = 0; j < _PB_NJ; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - j));
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(&c_row[j], vl);
      vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
      __riscv_vse64_v_f64m1(&c_row[j], vc, vl);
      j += (int)vl;
    }

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_scaled = alpha * a_row[k];
      DATA_TYPE *b_row = &B[k][0];
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - j));
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&c_row[j], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&b_row[j], vl);
        vc = __riscv_vfmacc_vf_f64m1(vc, a_scaled, vb, vl);
        __riscv_vse64_v_f64m1(&c_row[j], vc, vl);
        j += (int)vl;
      }
    }
#elif defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
    for (j = 0; j < _PB_NJ; ) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - j));
      vfloat32m1_t vc = __riscv_vle32_v_f32m1(&c_row[j], vl);
      vc = __riscv_vfmul_vf_f32m1(vc, beta, vl);
      __riscv_vse32_v_f32m1(&c_row[j], vc, vl);
      j += (int)vl;
    }

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_scaled = alpha * a_row[k];
      DATA_TYPE *b_row = &B[k][0];
      for (j = 0; j < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - j));
        vfloat32m1_t vc = __riscv_vle32_v_f32m1(&c_row[j], vl);
        vfloat32m1_t vb = __riscv_vle32_v_f32m1(&b_row[j], vl);
        vc = __riscv_vfmacc_vf_f32m1(vc, a_scaled, vb, vl);
        __riscv_vse32_v_f32m1(&c_row[j], vc, vl);
        j += (int)vl;
      }
    }
#else
    for (j = 0; j < _PB_NJ; j++)
      c_row[j] *= beta;

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_scaled = alpha * a_row[k];
      DATA_TYPE *b_row = &B[k][0];
      for (j = 0; j < _PB_NJ; j++)
        c_row[j] += a_scaled * b_row[j];
    }
#endif
  }
#pragma endscop
}

static
void kernel_gemver(int n,
                   DATA_TYPE alpha,
                   DATA_TYPE beta,
                   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
                   DATA_TYPE POLYBENCH_1D(u1,N,n),
                   DATA_TYPE POLYBENCH_1D(v1,N,n),
                   DATA_TYPE POLYBENCH_1D(u2,N,n),
                   DATA_TYPE POLYBENCH_1D(v2,N,n),
                   DATA_TYPE POLYBENCH_1D(w,N,n),
                   DATA_TYPE POLYBENCH_1D(x,N,n),
                   DATA_TYPE POLYBENCH_1D(y,N,n),
                   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

#if defined(__riscv_vector)
  if (sizeof(DATA_TYPE) == sizeof(float))
  {
    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE *Ai = A[i];
      float su1 = (float)u1[i];
      float su2 = (float)u2[i];
      size_t jj = 0;
      while (jj < (size_t)_PB_N) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - (int)jj));
        vfloat32m1_t va = __riscv_vle32_v_f32m1((const float *)(Ai + jj), vl);
        vfloat32m1_t vv1 = __riscv_vle32_v_f32m1((const float *)(v1 + jj), vl);
        vfloat32m1_t vv2 = __riscv_vle32_v_f32m1((const float *)(v2 + jj), vl);
        va = __riscv_vfmacc_vf_f32m1(va, su1, vv1, vl);
        va = __riscv_vfmacc_vf_f32m1(va, su2, vv2, vl);
        __riscv_vse32_v_f32m1((float *)(Ai + jj), va, vl);
        jj += vl;
      }
    }

    for (i = 0; i < _PB_N; i++) {
      float acc = (float)x[i];
      size_t jj = 0;
      while (jj < (size_t)_PB_N) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - (int)jj));
        vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float *)(y + jj), vl);
        vfloat32m1_t va = __riscv_vlse32_v_f32m1((const float *)&A[jj][i],
                                                 (ptrdiff_t)((ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE)),
                                                 vl);
        vfloat32m1_t vp = __riscv_vfmul_vv_f32m1(va, vy, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        vfloat32m1_t vs = __riscv_vfredusum_vs_f32m1_f32m1(vp, vzero, vl);
        acc += (float)beta * __riscv_vfmv_f_s_f32m1_f32(vs);
        jj += vl;
      }
      x[i] = (DATA_TYPE)acc;
    }

    {
      size_t ii = 0;
      while (ii < (size_t)_PB_N) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - (int)ii));
        vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float *)(x + ii), vl);
        vfloat32m1_t vz = __riscv_vle32_v_f32m1((const float *)(z + ii), vl);
        vx = __riscv_vfadd_vv_f32m1(vx, vz, vl);
        __riscv_vse32_v_f32m1((float *)(x + ii), vx, vl);
        ii += vl;
      }
    }

    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE *Ai = A[i];
      float acc = (float)w[i];
      size_t jj = 0;
      while (jj < (size_t)_PB_N) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - (int)jj));
        vfloat32m1_t va = __riscv_vle32_v_f32m1((const float *)(Ai + jj), vl);
        vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float *)(x + jj), vl);
        vfloat32m1_t vp = __riscv_vfmul_vv_f32m1(va, vx, vl);
        vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        vfloat32m1_t vs = __riscv_vfredusum_vs_f32m1_f32m1(vp, vzero, vl);
        acc += (float)alpha * __riscv_vfmv_f_s_f32m1_f32(vs);
        jj += vl;
      }
      w[i] = (DATA_TYPE)acc;
    }
  }
  else if (sizeof(DATA_TYPE) == sizeof(double))
  {
    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE *Ai = A[i];
      double su1 = (double)u1[i];
      double su2 = (double)u2[i];
      size_t jj = 0;
      while (jj < (size_t)_PB_N) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - (int)jj));
        vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)(Ai + jj), vl);
        vfloat64m1_t vv1 = __riscv_vle64_v_f64m1((const double *)(v1 + jj), vl);
        vfloat64m1_t vv2 = __riscv_vle64_v_f64m1((const double *)(v2 + jj), vl);
        va = __riscv_vfmacc_vf_f64m1(va, su1, vv1, vl);
        va = __riscv_vfmacc_vf_f64m1(va, su2, vv2, vl);
        __riscv_vse64_v_f64m1((double *)(Ai + jj), va, vl);
        jj += vl;
      }
    }

    for (i = 0; i < _PB_N; i++) {
      double acc = (double)x[i];
      size_t jj = 0;
      while (jj < (size_t)_PB_N) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - (int)jj));
        vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double *)(y + jj), vl);
        vfloat64m1_t va = __riscv_vlse64_v_f64m1((const double *)&A[jj][i],
                                                 (ptrdiff_t)((ptrdiff_t)n * (ptrdiff_t)sizeof(DATA_TYPE)),
                                                 vl);
        vfloat64m1_t vp = __riscv_vfmul_vv_f64m1(va, vy, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t vs = __riscv_vfredusum_vs_f64m1_f64m1(vp, vzero, vl);
        acc += (double)beta * __riscv_vfmv_f_s_f64m1_f64(vs);
        jj += vl;
      }
      x[i] = (DATA_TYPE)acc;
    }

    {
      size_t ii = 0;
      while (ii < (size_t)_PB_N) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - (int)ii));
        vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double *)(x + ii), vl);
        vfloat64m1_t vz = __riscv_vle64_v_f64m1((const double *)(z + ii), vl);
        vx = __riscv_vfadd_vv_f64m1(vx, vz, vl);
        __riscv_vse64_v_f64m1((double *)(x + ii), vx, vl);
        ii += vl;
      }
    }

    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE *Ai = A[i];
      double acc = (double)w[i];
      size_t jj = 0;
      while (jj < (size_t)_PB_N) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - (int)jj));
        vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)(Ai + jj), vl);
        vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double *)(x + jj), vl);
        vfloat64m1_t vp = __riscv_vfmul_vv_f64m1(va, vx, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t vs = __riscv_vfredusum_vs_f64m1_f64m1(vp, vzero, vl);
        acc += (double)alpha * __riscv_vfmv_f_s_f64m1_f64(vs);
        jj += vl;
      }
      w[i] = (DATA_TYPE)acc;
    }
  }
  else
#endif
  {
    for (i = 0; i < _PB_N; i++)
      for (j = 0; j < _PB_N; j++)
        A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];

    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE acc = x[i];
      for (j = 0; j < _PB_N; j++)
        acc = acc + beta * A[j][i] * y[j];
      x[i] = acc;
    }

    for (i = 0; i < _PB_N; i++)
      x[i] = x[i] + z[i];

    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE acc = w[i];
      for (j = 0; j < _PB_N; j++)
        acc = acc + alpha * A[i][j] * x[j];
      w[i] = acc;
    }
  }

#pragma endscop
}

static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE sumA = SCALAR_VAL(0.0);
      DATA_TYPE sumB = SCALAR_VAL(0.0);

#if defined(__riscv_vector) && defined(__has_include)
#if __has_include(<riscv_vector.h>)
#define KERNEL_GESUMMV_USE_RVV 1
#include <riscv_vector.h>
#endif
#endif

#if defined(KERNEL_GESUMMV_USE_RVV) && defined(DATA_TYPE_IS_DOUBLE)
      {
        DATA_TYPE *Ai = &A[i][0];
        DATA_TYPE *Bi = &B[i][0];
        size_t avl = (size_t)_PB_N;
        vfloat64m1_t accA = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
        vfloat64m1_t accB = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());

        j = 0;
        while (avl > 0)
          {
            size_t vl = __riscv_vsetvl_e64m1(avl);
            vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
            vfloat64m1_t vA = __riscv_vle64_v_f64m1(&Ai[j], vl);
            vfloat64m1_t vB = __riscv_vle64_v_f64m1(&Bi[j], vl);
            accA = __riscv_vfmacc_vv_f64m1(accA, vA, vx, vl);
            accB = __riscv_vfmacc_vv_f64m1(accB, vB, vx, vl);
            j += (int)vl;
            avl -= vl;
          }

        {
          size_t vlmax = __riscv_vsetvlmax_e64m1();
          DATA_TYPE bufA[64];
          DATA_TYPE bufB[64];
          size_t k;

          if (vlmax > 64) vlmax = 64;
          __riscv_vse64_v_f64m1(bufA, accA, vlmax);
          __riscv_vse64_v_f64m1(bufB, accB, vlmax);
          for (k = 0; k < vlmax; k++)
            {
              sumA += bufA[k];
              sumB += bufB[k];
            }
        }
      }
#elif defined(KERNEL_GESUMMV_USE_RVV) && defined(DATA_TYPE_IS_FLOAT)
      {
        DATA_TYPE *Ai = &A[i][0];
        DATA_TYPE *Bi = &B[i][0];
        size_t avl = (size_t)_PB_N;
        vfloat32m1_t accA = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvlmax_e32m1());
        vfloat32m1_t accB = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvlmax_e32m1());

        j = 0;
        while (avl > 0)
          {
            size_t vl = __riscv_vsetvl_e32m1(avl);
            vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[j], vl);
            vfloat32m1_t vA = __riscv_vle32_v_f32m1(&Ai[j], vl);
            vfloat32m1_t vB = __riscv_vle32_v_f32m1(&Bi[j], vl);
            accA = __riscv_vfmacc_vv_f32m1(accA, vA, vx, vl);
            accB = __riscv_vfmacc_vv_f32m1(accB, vB, vx, vl);
            j += (int)vl;
            avl -= vl;
          }

        {
          size_t vlmax = __riscv_vsetvlmax_e32m1();
          DATA_TYPE bufA[128];
          DATA_TYPE bufB[128];
          size_t k;

          if (vlmax > 128) vlmax = 128;
          __riscv_vse32_v_f32m1(bufA, accA, vlmax);
          __riscv_vse32_v_f32m1(bufB, accB, vlmax);
          for (k = 0; k < vlmax; k++)
            {
              sumA += bufA[k];
              sumB += bufB[k];
            }
        }
      }
#else
      for (j = 0; j < _PB_N; j++)
	{
	  sumA = A[i][j] * x[j] + sumA;
	  sumB = B[i][j] * x[j] + sumB;
	}
#endif

      tmp[i] = sumA;
      y[i] = alpha * sumA + beta * sumB;
    }
#pragma endscop

}

static
void kernel_gramschmidt(int m, int n,
                        DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                        DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
                        DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++) {
    nrm = SCALAR_VAL(0.0);
    for (i = 0; i < _PB_M; i++)
      nrm += A[i][k] * A[i][k];

    R[k][k] = SQRT_FUN(nrm);

    for (i = 0; i < _PB_M; i++)
      Q[i][k] = A[i][k] / R[k][k];

    for (j = k + 1; j < _PB_N; j++) {
      DATA_TYPE rkj = SCALAR_VAL(0.0);

      for (i = 0; i < _PB_M; i++)
        rkj += Q[i][k] * A[i][j];

      R[k][j] = rkj;

      for (i = 0; i < _PB_M; i++)
        A[i][j] = A[i][j] - Q[i][k] * rkj;
    }
  }
#pragma endscop

}

static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#pragma scop
  {
    const int nn = _PB_N;
    const DATA_TYPE c0 = SCALAR_VAL(0.125);
    const DATA_TYPE c1 = SCALAR_VAL(2.0);

    for (t = 1; t <= TSTEPS; t++) {

      for (i = 1; i < nn - 1; i++) {
        for (j = 1; j < nn - 1; j++) {
          DATA_TYPE *b_row     = &B[i][j][0];
          DATA_TYPE *a_row     = &A[i][j][0];
          DATA_TYPE *a_im1_row = &A[i-1][j][0];
          DATA_TYPE *a_ip1_row = &A[i+1][j][0];
          DATA_TYPE *a_jm1_row = &A[i][j-1][0];
          DATA_TYPE *a_jp1_row = &A[i][j+1][0];

#if defined(__riscv_vector) && defined(__riscv_flen) && (__riscv_flen >= 64) && defined(__has_include)
#if __has_include(<riscv_vector.h>)
#include <riscv_vector.h>
          {
            int rem = nn - 2;
            int kk = 1;
            while (rem > 0) {
              size_t vl = __riscv_vsetvl_e64m1((size_t)rem);

              vfloat64m1_t v_c   = __riscv_vle64_v_f64m1(&a_row[kk], vl);
              vfloat64m1_t v_ip1 = __riscv_vle64_v_f64m1(&a_ip1_row[kk], vl);
              vfloat64m1_t v_im1 = __riscv_vle64_v_f64m1(&a_im1_row[kk], vl);
              vfloat64m1_t v_jp1 = __riscv_vle64_v_f64m1(&a_jp1_row[kk], vl);
              vfloat64m1_t v_jm1 = __riscv_vle64_v_f64m1(&a_jm1_row[kk], vl);
              vfloat64m1_t v_kp1 = __riscv_vle64_v_f64m1(&a_row[kk + 1], vl);
              vfloat64m1_t v_km1 = __riscv_vle64_v_f64m1(&a_row[kk - 1], vl);

              vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(v_ip1, v_im1, vl);
              v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_jp1, vl);
              v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_jm1, vl);
              v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_kp1, vl);
              v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_km1, vl);

              vfloat64m1_t v_6c = __riscv_vfmul_vf_f64m1(v_c, (double)6.0, vl);
              vfloat64m1_t v_d  = __riscv_vfsub_vv_f64m1(v_sum, v_6c, vl);
              vfloat64m1_t v_r  = __riscv_vfmacc_vf_f64m1(v_c, (double)c0, v_d, vl);

              __riscv_vse64_v_f64m1(&b_row[kk], v_r, vl);

              kk += (int)vl;
              rem -= (int)vl;
            }
          }
#else
          for (k = 1; k < nn - 1; k++) {
            DATA_TYPE center = a_row[k];
            b_row[k] = c0 * (a_ip1_row[k] - c1 * center + a_im1_row[k])
                     + c0 * (a_jp1_row[k] - c1 * center + a_jm1_row[k])
                     + c0 * (a_row[k+1]   - c1 * center + a_row[k-1])
                     + center;
          }
#endif
#else
          for (k = 1; k < nn - 1; k++) {
            DATA_TYPE center = a_row[k];
            b_row[k] = c0 * (a_ip1_row[k] - c1 * center + a_im1_row[k])
                     + c0 * (a_jp1_row[k] - c1 * center + a_jm1_row[k])
                     + c0 * (a_row[k+1]   - c1 * center + a_row[k-1])
                     + center;
          }
#endif
        }
      }

      for (i = 1; i < nn - 1; i++) {
        for (j = 1; j < nn - 1; j++) {
          DATA_TYPE *a_row     = &A[i][j][0];
          DATA_TYPE *b_row     = &B[i][j][0];
          DATA_TYPE *b_im1_row = &B[i-1][j][0];
          DATA_TYPE *b_ip1_row = &B[i+1][j][0];
          DATA_TYPE *b_jm1_row = &B[i][j-1][0];
          DATA_TYPE *b_jp1_row = &B[i][j+1][0];

#if defined(__riscv_vector) && defined(__riscv_flen) && (__riscv_flen >= 64) && defined(__has_include)
#if __has_include(<riscv_vector.h>)
          {
            int rem = nn - 2;
            int kk = 1;
            while (rem > 0) {
              size_t vl = __riscv_vsetvl_e64m1((size_t)rem);

              vfloat64m1_t v_c   = __riscv_vle64_v_f64m1(&b_row[kk], vl);
              vfloat64m1_t v_ip1 = __riscv_vle64_v_f64m1(&b_ip1_row[kk], vl);
              vfloat64m1_t v_im1 = __riscv_vle64_v_f64m1(&b_im1_row[kk], vl);
              vfloat64m1_t v_jp1 = __riscv_vle64_v_f64m1(&b_jp1_row[kk], vl);
              vfloat64m1_t v_jm1 = __riscv_vle64_v_f64m1(&b_jm1_row[kk], vl);
              vfloat64m1_t v_kp1 = __riscv_vle64_v_f64m1(&b_row[kk + 1], vl);
