{
  int i, j, k;

#pragma scop
  for (i = 0; i < n; i++) {
    double *Ai = A[i];

    for (j = 0; j < i; j++) {
      double sum = Ai[j];

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic)
      {
        int rem = j;
        int kk = 0;
        while (rem > 0) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)rem);
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[kk], vl);

          double tmp_kj[vl];
          size_t t;
          for (t = 0; t < vl; ++t)
            tmp_kj[t] = A[kk + (int)t][j];

          vfloat64m1_t vb = __riscv_vle64_v_f64m1(tmp_kj, vl);
          vfloat64m1_t vmul = __riscv_vfmul_vv_f64m1(va, vb, vl);
          vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
          vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vmul, vzero, vl);
          sum -= __riscv_vfmv_f_s_f64m1_f64(vred);

          kk += (int)vl;
          rem -= (int)vl;
        }
      }
#else
      for (k = 0; k < j; k++) {
        sum -= Ai[k] * A[k][j];
      }
#endif

      Ai[j] = sum / A[j][j];
    }

    for (j = i; j < n; j++) {
      double sum = Ai[j];

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic)
      {
        int rem = i;
        int kk = 0;
        while (rem > 0) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)rem);
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[kk], vl);

