static
void kernel_ludcmp(int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      DATA_TYPE sum = (DATA_TYPE)0;
      DATA_TYPE *Aj = A[j];
      for (k = 0; k < j; k++) {
        sum += Ai[k] * A[k][j];
      }
      w = Ai[j] - sum;
      Ai[j] = w / Aj[j];
    }

    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = (DATA_TYPE)0;
      for (k = 0; k < i; k++) {
        sum += Ai[k] * A[k][j];
      }
      Ai[j] = Ai[j] - sum;
    }
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE sum = (DATA_TYPE)0;
    for (j = 0; j < i; j++) {
      sum += Ai[j] * y[j];
    }
    y[i] = b[i] - sum;
  }

  for (i = _PB_N - 1; i >= 0; i--) {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE sum = (DATA_TYPE)0;
    for (j = i + 1; j < _PB_N; j++) {
      sum += Ai[j] * x[j];
    }
    w = y[i] - sum;
    x[i] = w / Ai[i];
  }
#pragma endscop
}

