      vfloat64m1_t vs = __riscv_vfmul_vv_f64m1(va, vy, vl);
      vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
      vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vs, vzero, vl);
      acc += __riscv_vfmv_f_s_f64m1_f64(vred);
      j += (int)vl;
    }
    x1[i] = acc;
  }

  for (i = 0; i < _PB_N; i++) {
    double acc = x2[i];
    j = 0;
    for (; j < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      vuint64m1_t vidx = __riscv_vid_v_u64m1(vl);
      vuint64m1_t vstride = __riscv_vmv_v_x_u64m1((uint64_t)n, vl);
      vuint64m1_t voff_elems = __riscv_vmul_vv_u64m1(vidx, vstride, vl);
      vuint64m1_t voff_bytes = __riscv_vsll_vx_u64m1(voff_elems, 3, vl);
      const double *base = (const double *)&A[j][i];
      vfloat64m1_t va = __riscv_vluxei64_v_f64m1(base, voff_bytes, vl);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1(((const double *)y_2) + j, vl);
      vfloat64m1_t vs = __riscv_vfmul_vv_f64m1(va, vy, vl);
      vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
      vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vs, vzero, vl);
      acc += __riscv_vfmv_f_s_f64m1_f64(vred);
      j += (int)vl;
    }
    x2[i] = acc;
  }
# endif
#else
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc = x1[i];
    for (j = 0; j < _PB_N; j++)
      acc = acc + A[i][j] * y_1[j];
    x1[i] = acc;
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc = x2[i];
    for (j = 0; j < _PB_N; j++)
      acc = acc + A[j][i] * y_2[j];
    x2[i] = acc;
  }
#endif
#pragma endscop
}

static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
                           DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = _PB_N - 1; i >= 0; --i) {
    for (j = i + 1; j < _PB_N; ++j) {
      DATA_TYPE best = table[i][j];

      if (j - 1 >= 0) {
        DATA_TYPE v = table[i][j - 1];
        if (v > best) best = v;
      }

      if (i + 1 < _PB_N) {
        DATA_TYPE v = table[i + 1][j];
        if (v > best) best = v;
      }

      if (j - 1 >= 0 && i + 1 < _PB_N) {
        DATA_TYPE v = table[i + 1][j - 1];
        if (i < j - 1)
          v = v + match(seq[i], seq[j]);
        if (v > best) best = v;
      }

      for (k = i + 1; k < j; ++k) {
        DATA_TYPE cand = table[i][k] + table[k + 1][j];
        if (cand > best) best = cand;
      }

      table[i][j] = best;
    }
  }
#pragma endscop
}

static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    for (i = 1; i <= _PB_N - 2; i++) {
      DATA_TYPE *rowm1 = &A[i - 1][0];
      DATA_TYPE *row0  = &A[i][0];
      DATA_TYPE *rowp1 = &A[i + 1][0];

      j = 1;

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
      for (; j + 3 <= _PB_N - 2; j += 4) {
        DATA_TYPE a0 = (rowm1[j-1] + rowm1[j] + rowm1[j+1]
                      + row0[j-1]  + row0[j]  + row0[j+1]
                      + rowp1[j-1] + rowp1[j] + rowp1[j+1]) / SCALAR_VAL(9.0);
        row0[j] = a0;

        DATA_TYPE a1 = (rowm1[j]   + rowm1[j+1] + rowm1[j+2]
                      + row0[j]    + row0[j+1]  + row0[j+2]
                      + rowp1[j]   + rowp1[j+1] + rowp1[j+2]) / SCALAR_VAL(9.0);
        row0[j+1] = a1;

        DATA_TYPE a2 = (rowm1[j+1] + rowm1[j+2] + rowm1[j+3]
                      + row0[j+1]  + row0[j+2]  + row0[j+3]
                      + rowp1[j+1] + rowp1[j+2] + rowp1[j+3]) / SCALAR_VAL(9.0);
        row0[j+2] = a2;

        DATA_TYPE a3 = (rowm1[j+2] + rowm1[j+3] + rowm1[j+4]
                      + row0[j+2]  + row0[j+3]  + row0[j+4]
                      + rowp1[j+2] + rowp1[j+3] + rowp1[j+4]) / SCALAR_VAL(9.0);
        row0[j+3] = a3;
      }

      for (; j <= _PB_N - 2; j++) {
        row0[j] = (rowm1[j-1] + rowm1[j] + rowm1[j+1]
                 + row0[j-1]  + row0[j]  + row0[j+1]
                 + rowp1[j-1] + rowp1[j] + rowp1[j+1]) / SCALAR_VAL(9.0);
      }
    }
  }
#pragma endscop

}

static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE aii = A[i][i];
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE bij = B[i][j];
      DATA_TYPE alpha_bij = alpha * bij;
      temp2 = 0;

      for (k = 0; k < i; k++) {
        DATA_TYPE aik = A[i][k];
        C[k][j] += alpha_bij * aik;
        temp2 += B[k][j] * aik;
      }

      C[i][j] = beta * C[i][j] + alpha_bij * aii + alpha * temp2;
    }
  }
#pragma endscop

}

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *c_i = C[i];
    DATA_TYPE *a_i = A[i];
    DATA_TYPE *b_i = B[i];

    for (j = 0; j <= i; j++)
      c_i[j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = a_i[k] * alpha;
      DATA_TYPE bik_alpha = b_i[k] * alpha;

      for (j = 0; j <= i; j++)
        c_i[j] += A[j][k] * bik_alpha + B[j][k] * aik_alpha;
    }
  }
#pragma endscop

}

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *c_row = &C[i][0];
    DATA_TYPE *a_i_row = &A[i][0];

    for (j = 0; j <= i; j++)
      c_row[j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * a_i_row[k];
      for (j = 0; j <= i; j++)
        c_row[j] += aik_alpha * A[j][k];
    }
  }
#pragma endscop

}

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE sum = b[i];

#if defined(__riscv_vector) && defined(__GNUC__) && !defined(__clang__) && !defined(__cplusplus)
      {
        DATA_TYPE *Li = L[i];
        j = 0;

#if defined(DATA_TYPE_IS_DOUBLE)
        if (i > 0)
          {
            size_t remaining = (size_t)i;
            vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1((double)0.0, 1);
            while (remaining > 0)
              {
                size_t vl = __riscv_vsetvl_e64m1(remaining);
                vfloat64m1_t vL = __riscv_vle64_v_f64m1(&Li[j], vl);
                vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
                vacc = __riscv_vfmacc_vv_f64m1(vacc, vL, vx, vl);
                j += (int)vl;
                remaining -= vl;
              }
            {
              vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1((double)0.0, 1);
              vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vacc, vzero, 1);
              sum -= __riscv_vfmv_f_s_f64m1_f64(vred);
            }
          }
#elif defined(DATA_TYPE_IS_FLOAT)
        if (i > 0)
          {
            size_t remaining = (size_t)i;
            vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1((float)0.0f, 1);
            while (remaining > 0)
              {
                size_t vl = __riscv_vsetvl_e32m1(remaining);
                vfloat32m1_t vL = __riscv_vle32_v_f32m1(&Li[j], vl);
                vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[j], vl);
                vacc = __riscv_vfmacc_vv_f32m1(vacc, vL, vx, vl);
                j += (int)vl;
                remaining -= vl;
              }
            {
              vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1((float)0.0f, 1);
              vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vacc, vzero, 1);
              sum -= __riscv_vfmv_f_s_f32m1_f32(vred);
            }
          }
#else
        for (j = 0; j < i; j++)
          sum -= L[i][j] * x[j];
#endif
      }
#else
      for (j = 0; j < i; j++)
        sum -= L[i][j] * x[j];
#endif

      x[i] = sum / L[i][i];
    }
#pragma endscop

}

static
void kernel_trmm(int m, int n,
		 double alpha,
		 double POLYBENCH_2D(A,M,M,m,m),
		 double POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector) && defined(__riscv_v_intrinsic)
  for (i = 0; i < _PB_M; ++i) {
    int j0 = 0;
    for (; j0 < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j0));
      vfloat64m1_t bvec = __riscv_vle64_v_f64m1(&B[i][j0], vl);

      for (k = i + 1; k < _PB_M; ++k) {
        vfloat64m1_t bk = __riscv_vle64_v_f64m1(&B[k][j0], vl);
        bvec = __riscv_vfmacc_vf_f64m1(bvec, A[k][i], bk, vl);
      }

      bvec = __riscv_vfmul_vf_f64m1(bvec, alpha, vl);
      __riscv_vse64_v_f64m1(&B[i][j0], bvec, vl);
      j0 += (int)vl;
    }
  }
#else
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_N; j++) {
      double Bij = B[i][j];
      for (k = i + 1; k < _PB_M; k++)
        Bij += A[k][i] * B[k][j];
      B[i][j] = alpha * Bij;
    }
#endif
#pragma endscop
}
